selfChecks.cmd:
mkdir -p /tmp/selfcheck && cat > /tmp/selfcheck/client-mock.test.mjs <<'EOF'
import assert from 'node:assert/strict';
import { test } from 'node:test';
import { pathToFileURL } from 'node:url';
const root = pathToFileURL(process.cwd() + '/');
test('client module can be replaced', async (t) => {
  t.mock.module(new URL('lib/llm/client.ts', root).href, {
    namedExports: {
      streamReply: async function* () {
        yield { type: 'text', text: 'Hel' };
        yield { type: 'stop', reason: 'filtered' };
      },
    },
  });
  const { chatEvents, SAFE_MESSAGE } = await import(new URL('lib/chat/reply.ts', root).href);
  const events = [];
  for await (const event of chatEvents([{ role: 'user', content: 'hi' }])) events.push(event);
  assert.deepEqual(events, [
    { type: 'delta', text: 'Hel' },
    { type: 'replace', text: SAFE_MESSAGE },
    { type: 'end', reason: 'filtered' },
  ]);
});
EOF
node --test --experimental-test-module-mocks /tmp/selfcheck/client-mock.test.mjs
